import{_ as a,o as e,c as d,a3 as o}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"组件何时抽象","description":"","frontmatter":{"title":"组件何时抽象","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/ui/component-abstraction.md","filePath":"frontend/decisions/ui/component-abstraction.md","lastUpdated":1785589115000}'),r={name:"frontend/decisions/ui/component-abstraction.md"};function i(l,t,c,h,n,s){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="组件何时抽象" tabindex="-1">组件何时抽象 <a class="header-anchor" href="#组件何时抽象" aria-label="Permalink to &quot;组件何时抽象&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>组件抽象的目标不是消除所有重复，而是为已经稳定的共同语义建立一个可维护契约。过早抽象会把尚未理解的差异塞进布尔参数和插槽，过晚抽象则导致交互、无障碍和修复在多个页面漂移。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>“出现三次就抽象”只能作为提醒，不能作为规则。三段相似 JSX 或模板可能服务不同业务，未来会继续分化；一个只出现一次的日期选择器也可能因为复杂交互和无障碍要求值得封装。</p><p>真正要判断的是变化原因是否相同、消费者是否需要同一契约，以及谁愿意长期拥有这个抽象。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-抽象必须保持的条件" tabindex="-1">2.1 抽象必须保持的条件 <a class="header-anchor" href="#_2-1-抽象必须保持的条件" aria-label="Permalink to &quot;2.1 抽象必须保持的条件&quot;">​</a></h3><ul><li>组件不能隐藏权限、金额等业务规则的真实所有者；</li><li>键盘、焦点、错误提示和语义不能因封装退化；</li><li>公开 Props、Events、Slots 和样式扩展点有可测试行为；</li><li>抽象有负责人、弃用方式和版本范围；</li><li>失败时消费者能够定位到领域、组件还是基础设施。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较共同语义、变化同步程度、实现复杂度、消费者数量、错误代价、可访问性复用、API 复杂度、定制需求和迁移成本。</p><p>可使用一个简单问题检验：如果两个使用方明天分别提出变化，团队预计会同时修改还是朝不同方向修改？</p><h2 id="_3-候选方式" tabindex="-1">3. 候选方式 <a class="header-anchor" href="#_3-候选方式" aria-label="Permalink to &quot;3. 候选方式&quot;">​</a></h2><h3 id="_3-1-保留局部重复" tabindex="-1">3.1 保留局部重复 <a class="header-anchor" href="#_3-1-保留局部重复" aria-label="Permalink to &quot;3.1 保留局部重复&quot;">​</a></h3><p>适合语义尚不明确、实现很小或需求可能分化的代码。重复能保留变化自由，但应记录何时重新观察，避免永久复制高风险行为。</p><h3 id="_3-2-提取无-ui-的逻辑" tabindex="-1">3.2 提取无 UI 的逻辑 <a class="header-anchor" href="#_3-2-提取无-ui-的逻辑" aria-label="Permalink to &quot;3.2 提取无 UI 的逻辑&quot;">​</a></h3><p>当多个页面只共享格式化、校验或请求编排时，优先提取函数或 composable，而不强迫 DOM 和视觉结构一致。这通常比“万能组件”更稳定。</p><h3 id="_3-3-领域组件" tabindex="-1">3.3 领域组件 <a class="header-anchor" href="#_3-3-领域组件" aria-label="Permalink to &quot;3.3 领域组件&quot;">​</a></h3><p>围绕清楚业务语义封装，例如 <code>MoneyInput</code>、<code>OrderStatus</code>、<code>PermissionGuard</code>。它允许固化领域规则和可访问性，适合变化原因一致的消费者。</p><h3 id="_3-4-基础-ui-组件" tabindex="-1">3.4 基础 UI 组件 <a class="header-anchor" href="#_3-4-基础-ui-组件" aria-label="Permalink to &quot;3.4 基础 UI 组件&quot;">​</a></h3><p>按钮、对话框、选择器等基础交互需要稳定、低业务含义的 API 和严格质量标准。它们通常属于组件库，不应由单个业务页面顺手抽象。</p><h3 id="_3-5-schema-或配置驱动组件" tabindex="-1">3.5 Schema 或配置驱动组件 <a class="header-anchor" href="#_3-5-schema-或配置驱动组件" aria-label="Permalink to &quot;3.5 Schema 或配置驱动组件&quot;">​</a></h3><p>只有结构高度重复、差异能被有限数据模型表达且需要批量生成时才采用。不断加入回调、条件表达式和逃生插槽，说明配置模型正在重建一套难维护的 UI 语言。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><p>以四个页面中的“选择客户”交互为例：它们都需要远程搜索、分页、键盘导航、已选项展示和权限过滤，只在单选/多选与结果字段上不同。</p><table tabindex="0"><thead><tr><th>方案</th><th>收益</th><th>风险</th></tr></thead><tbody><tr><td>四份局部实现</td><td>每页自由变化</td><td>重复请求竞态、键盘和权限修复</td></tr><tr><td>只提取查询 composable</td><td>复用数据流，UI 保持自由</td><td>可访问性交互仍重复</td></tr><tr><td><code>CustomerPicker</code> 领域组件</td><td>统一语义、权限和交互</td><td>需要设计清楚值模型和扩展点</td></tr><tr><td>通用 <code>EntityPicker</code></td><td>可覆盖更多实体</td><td>API 易被实体差异和条件参数淹没</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>推荐先抽象 <code>CustomerPicker</code>，不直接创建 <code>EntityPicker</code>。公开契约只包含 <code>modelValue</code>、<code>multiple</code>、允许的客户范围和 <code>change</code>/<code>error</code> 事件；搜索、取消旧请求、分页、键盘和权限过滤由组件负责。</p><p>当供应商、仓库等至少两个实体证明具有相同查询和交互契约后，再把无领域差异的内核下沉为私有 <code>RemotePickerCore</code>。业务页面继续使用语义明确的薄包装，不直接面对万能配置。</p><p>另一个反例是四个审批面板：虽然布局相似，但订单、退款和合同的权限、状态转换与审计不同。这里应复用按钮和布局原语，保留领域流程组件，不抽象成几十个布尔参数的 <code>ApprovalPanel</code>。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>领域组件集中修复请求竞态、键盘和权限展示，消费者减少重复。代价是组件团队承担 API 稳定、文档、测试和变更协调，页面的极端定制需要明确拒绝或通过组合点支持。</p><p>抽象后的成功不是代码行数下降，而是同类缺陷减少、修改集中且调用端更能表达业务。若新增一个需求总要修改核心并增加条件，抽象边界可能错误。</p><p>退出成本取决于公开 API。保持值模型和事件简单，允许消费者用本地 UI 替换，避免组件成为业务数据唯一存储。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>不要只因视觉相似就合并不同业务流程。</li><li>不要用十几个布尔 Props 表达互斥模式，应拆分语义组件或使用清楚变体。</li><li>不要把页面所有布局塞进一个“可配置页面”组件。</li><li>单次使用但交互高风险的控件仍可能值得封装。</li><li>抽象无人负责时，复制小段稳定代码可能更便宜。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>四个页面的客户选择是否抽象</td></tr><tr><td>硬约束</td><td>权限过滤一致；键盘可用；请求可取消；单选和多选都支持</td></tr><tr><td>候选</td><td>保留重复、查询 composable、<code>CustomerPicker</code>、通用 <code>EntityPicker</code></td></tr><tr><td>决定</td><td>提取 <code>CustomerPicker</code>，内含私有查询 composable</td></tr><tr><td>公共契约</td><td>值、选择模式、客户范围、变更和错误事件</td></tr><tr><td>明确排除</td><td>不支持任意实体 Schema；不封装审批业务</td></tr><tr><td>接受代价</td><td>组件所有权、回归测试和消费者协调</td></tr><tr><td>成功指标</td><td>重复实现删除数、同类缺陷、Props 增长、修改影响消费者数</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>消费者需求开始明显分化、公共 Props 超过约定预算、超过 30% 变更只服务单个页面、基础内核被第二个实体真实复用，或维护成本高于重复实现时复查。复查结果可以是下沉逻辑、拆分组件或直接内联，不必总是继续抽象。</p>',40)])])}const b=a(r,[["render",i]]);export{u as __pageData,b as default};
